<?php require_once __DIR__.'/../../app/bootstrap.php';$u=auth();if($u['role']!=='driver'||$_SERVER['REQUEST_METHOD']!=='PATCH')out(['error'=>'Forbidden'],403);$d=input();$status=$d['status']??'';if(!in_array($status,['picked_up','delivered'],true))out(['error'=>'Invalid status'],422);$s=db()->prepare("UPDATE orders SET status=? WHERE id=? AND driver_id=?");$s->execute([$status,(int)($d['order_id']??0),$u['id']]);out(['success'=>$s->rowCount()>0]);
